import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { Input } from "@/registry/erbium/ui/input";
import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import {
  Sheet,
  SheetClose,
  SheetPanel,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/registry/erbium/ui/sheet";

const SHEET_SIDES = ["top", "right", "bottom", "left"] as const;

type SheetSide = (typeof SHEET_SIDES)[number];

export default function SheetSide() {
  return (
    <div className="grid grid-cols-2 gap-2">
      {SHEET_SIDES.map((side) => (
        <Sheet key={side}>
          <SheetTrigger render={<Button variant="outline">{side}</Button>} />
          <SheetPanel side={side}>
            <SheetHeader>
              <SheetTitle>Edit profile</SheetTitle>
              <SheetDescription>
                Make changes to your profile here. Click save when you&apos;re done.
              </SheetDescription>
            </SheetHeader>
            <SheetContent className="grid content-start gap-4">
              <Field className="grid grid-cols-4 items-center gap-4">
                <FieldLabel className="text-end">Name</FieldLabel>
                <Input defaultValue="Pedro Duarte" className="col-span-3" />
              </Field>
              <Field className="grid grid-cols-4 items-center gap-4">
                <FieldLabel className="text-end">Username</FieldLabel>
                <Input defaultValue="@peduarte" className="col-span-3" />
              </Field>
            </SheetContent>
            <SheetFooter>
              <SheetClose render={<Button>Save changes</Button>} />
            </SheetFooter>
          </SheetPanel>
        </Sheet>
      ))}
    </div>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import {
  Sheet,
  SheetPanel,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@/registry/erbium/ui/sheet";

export default function SheetNoCloseButton() {
  return (
    <Sheet>
      <SheetTrigger render={<Button variant="outline" />}>Open Sheet</SheetTrigger>
      <SheetPanel showCloseButton={false}>
        <SheetHeader>
          <SheetTitle>No Close Button</SheetTitle>
          <SheetDescription>
            This sheet doesn&apos;t have a close button in the top-right corner. Click outside to
            close.
          </SheetDescription>
        </SheetHeader>
        <SheetContent>Review your changes here.</SheetContent>
      </SheetPanel>
    </Sheet>
  );
}

