const meta = {
  component: Sheet,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "Displays supporting content beside or above the main screen. `SheetPanel` owns the popup shell, while a direct `SheetContent` child provides the required padded, scrollable body. Optional header and footer sections go before and after the content.

**Import:** `@/registry/erbium/ui/sheet`

## Usage

```tsx
import {
  Sheet,
  SheetClose,
  SheetPanel,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetContent,
  SheetTitle,
  SheetTrigger,
} from "@/registry/erbium/ui/sheet";
import { Button } from "@/registry/erbium/ui/button";
```

```tsx
<Sheet>
  <SheetTrigger render={<Button variant="outline">Open</Button>} />
  <SheetPanel>
    <SheetHeader>
      <SheetTitle>Are you absolutely sure?</SheetTitle>
      <SheetDescription>This action cannot be undone.</SheetDescription>
    </SheetHeader>
    <SheetContent>Content</SheetContent>
    <SheetFooter>Actions</SheetFooter>
  </SheetPanel>
</Sheet>
```

## Composition

Use the following composition to build a `Sheet`:

```text
Sheet
├── SheetTrigger
└── SheetPanel
    ├── SheetHeader
    │   ├── SheetTitle
    │   └── SheetDescription
    ├── SheetContent
    └── SheetFooter
```

## Base UI documentation

Explore the underlying primitives and their API reference.

- [Dialog](https://base-ui.com/react/components/dialog)",
      },
    },
  },
} satisfies Meta<typeof Sheet>;

export default { ...meta, title: "Overlays & menus/Sheet",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

